import React, { useState, useEffect } from 'react';
import { navigate } from 'gatsby';
import { useAuth } from '../../context/AuthContext';
import { FaThLarge, FaImages, FaSignOutAlt, FaBars, FaTimes } from 'react-icons/fa';
import '../../styles/cms.css';
import logo from '../../images/logo.jpg';

interface CMSLayoutProps {
  children: React.ReactNode;
  activePage: 'dashboard' | 'images';
}

const CMSLayout: React.FC<CMSLayoutProps> = ({ children, activePage }) => {
  const { isAuthenticated, user, logout } = useAuth();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const handleNav = (path: string) => {
    setSidebarOpen(false);
    navigate(path);
  };

  return (
    <div className="cms-layout">
      {/* Mobile header */}
      <div className="cms-mobile-header">
        <img src={logo} alt="Echo Elite" />
        <span>Echo Elite CMS</span>
        <button className="cms-hamburger" onClick={() => setSidebarOpen(!sidebarOpen)}>
          {sidebarOpen ? <FaTimes /> : <FaBars />}
        </button>
      </div>

      {/* Overlay */}
      <div
        className={`cms-sidebar-overlay ${sidebarOpen ? 'open' : ''}`}
        onClick={() => setSidebarOpen(false)}
      />

      {/* Sidebar */}
      <aside className={`cms-sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="cms-sidebar-header">
          <img src={logo} alt="Echo Elite" />
          <div>
            <div className="cms-brand">Echo Elite</div>
            <div className="cms-brand-sub">Content Manager</div>
          </div>
        </div>

        <nav className="cms-sidebar-nav">
          <button
            className={`cms-nav-item ${activePage === 'dashboard' ? 'active' : ''}`}
            onClick={() => handleNav('/dashboard')}
          >
            <FaThLarge /> Dashboard
          </button>
          <button
            className={`cms-nav-item ${activePage === 'images' ? 'active' : ''}`}
            onClick={() => handleNav('/dashboard/images')}
          >
            <FaImages /> Images
          </button>
        </nav>

        <div className="cms-sidebar-footer">
          <div style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.5)', marginBottom: '0.5rem' }}>
            {user?.email}
          </div>
          <button className="cms-logout-btn" onClick={handleLogout}>
            <FaSignOutAlt /> Sign Out
          </button>
        </div>
      </aside>

      {/* Main content */}
      <main className="cms-main">
        {children}
      </main>
    </div>
  );
};

export default CMSLayout;
